249	    /**
250	     * Loads the owner with the given id and, when it exists, produces the response through
251	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
252	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
253	     * the not-found response are written in exactly one place rather than copied into each method.
254	     *
255	     * @param ownerId the id of the owner to load
256	     * @param action builds the response for an existing owner
257	     * @param <T> the response body type
258	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
259	     */
260	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner == null) {
263	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
264	        }
265	        return action.apply(owner);
266	    }
267	
268	    /**
269	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
270	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
271	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
272	     * return their owner through this method, so an owner is decorated identically on either path
273	     * and each derived field is computed in exactly one place.
274	     *
275	     * @param owner the persisted owner to represent
276	     * @return the owner DTO with its derived read-only fields populated
277	     */
278	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
279	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
280	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
281	        ownerDto.setIdentityKey(identityKey(owner));
282	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
283	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
284	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
285	        return ownerDto;
286	    }
287	
288	    /**
289	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
290	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
291	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
292	     * blank (e.g. {@code "   "}). The offending field names are reported through an
293	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
294	     * as a 400 response carrying an {@code errors} array of field names.
295	     *
296	     * @param ownerFieldsDto the submitted owner fields
297	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
298	     */
299	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
300	        List<String> blankFields = new ArrayList<>();
301	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
302	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
303	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
304	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
305	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
306	        if (!blankFields.isEmpty()) {
307	            throw new InvalidOwnerFieldsException(blankFields);
308	        }
309	    }
310	
311	    private void addIfBlank(List<String> blankFields, String field, String value) {
312	        if (value != null && value.isBlank()) {
313	            blankFields.add(field);
314	        }
315	    }
316	
317	    /**
318	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
319	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
320	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
321	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
322	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
323	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
324	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
325	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
326	     *
327	     * @param city the city of the owner being created
328	     * @param postcode the supplied postcode, or {@code null} when omitted
329	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
330	     */
331	    private void rejectInvalidPostcode(String city, String postcode) {
332	        if (postcode == null || postcode.isBlank()) {
333	            return;
334	        }
335	        Region.forCity(city).ifPresent(region -> {
336	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
337	                throw new InvalidOwnerPostcodeException(postcode, city);
338	            }
339	        });
340	    }
341	
342	    /**
343	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
344	     * the {@code customerCode}.
345	     */
346	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
347	
348	    /**
349	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
350	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
351	     * its {@code postcode} (falling back to its {@code city}) through the shared
352	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
353	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
354	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
355	     * function of the owner's region and telephone-plus-name identity.
356	     *
357	     * @param owner the owner being created, with its telephone already normalized
358	     * @return the formatted customer code
359	     */
360	    private String customerCode(Owner owner) {
361	        String region = Region.code(owner.getPostcode(), owner.getCity());
362	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
363	        return region + "-" + hash8;
364	    }
365	
366	    /**
367	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
368	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
369	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
370	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
371	     * new owner and surfaced as the read-only {@code namesakeCount} field.
372	     *
373	     * @param firstName the first name of the owner being created
374	     * @param lastName the last name of the owner being created
375	     * @return the number of existing owners with the same first and last name (case-insensitive)
376	     */
377	    private int namesakeCount(String firstName, String lastName) {
378	        return (int) this.clinicService.findAllOwners().stream()
379	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
380	                && equalsIgnoreCase(owner.getLastName(), lastName))
381	            .count();
382	    }
383	
384	    private boolean equalsIgnoreCase(String a, String b) {
385	        return a == null ? b == null : a.equalsIgnoreCase(b);
386	    }
387	
388	    /**
389	     * The maximum number of owners a single city may contain. Once a city already holds this many
390	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
391	     */
392	    private static final long MAX_OWNERS_PER_CITY = 50L;
393	
394	    /**
395	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
396	     * owners. Existing owners are matched to the requested city case-insensitively (using
397	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
398	     * the per-city counting used for the customer code. A city at capacity is reported through an
399	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
400	     * 409 Conflict response.
401	     *
402	     * @param city the city of the owner being created
403	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
404	     */
405	    private void rejectCityAtCapacity(String city) {
406	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
407	            throw new OwnerCityAtCapacityException(city);
408	        }
409	    }
410	
411	    /**
412	     * Counts the existing owners whose {@code city} matches the given city, compared
413	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
414	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
415	     *
416	     * @param city the city to count owners for
417	     * @return the number of existing owners in that city
418	     */
419	    private long ownersInCity(String city) {
420	        return this.clinicService.findAllOwners().stream()
421	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
422	            .count();
423	    }
424	
425	    /**
426	     * The maximum number of owners that may be registered on a single day. Once this many owners
427	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
428	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
429	     */
430	    private static final long MAX_OWNERS_PER_DAY = 100L;
431	
432	    /**
433	     * Resolves the effective registration date for a create request: the value supplied in the
434	     * request when present, otherwise the server's current date. The result is the raw effective
435	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
436	     *
437	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
438	     * @return the supplied date, or today when none was supplied
439	     */
440	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
441	        return suppliedDate != null ? suppliedDate : LocalDate.now();
442	    }
443	
444	    /**
445	     * Rejects a create request whose supplied {@code registrationDate} lies after the server's
446	     * current date. A registration date may be supplied to backdate a create - and is defaulted to
447	     * today when omitted - but it may never be in the future. The check is applied to the raw
448	     * supplied value before the business-day adjustment ({@link #businessDay(LocalDate)}), so a
449	     * future date is rejected regardless of how that adjustment would move it. A future date is
450	     * reported through a {@link FutureRegistrationDateException}, which the
451	     * {@code ExceptionControllerAdvice} renders as a 400 Bad Request response naming the
452	     * {@code registrationDate} field.
453	     *
454	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
455	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
456	     */
457	    private void rejectFutureRegistrationDate(LocalDate suppliedDate) {
458	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
459	            throw new FutureRegistrationDateException(suppliedDate);
460	        }
461	    }
462	
463	    /**
464	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
465	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
466	     * the effective registration date so that a weekend value - whether supplied in the request or
467	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
468	     * registration date (such as the membership number's year segment and the daily create-limit
469	     * bucket) uses the adjusted business day.
470	     *
471	     * @param date the effective registration date
472	     * @return the same date when it is a weekday, otherwise the next Monday
473	     */
474	    private LocalDate businessDay(LocalDate date) {
475	        DayOfWeek dayOfWeek = date.getDayOfWeek();
476	        if (dayOfWeek == DayOfWeek.SATURDAY) {
477	            return date.plusDays(2);
478	        }
479	        if (dayOfWeek == DayOfWeek.SUNDAY) {
480	            return date.plusDays(1);
481	        }
482	        return date;
483	    }
484	
485	    /**
486	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
487	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
488	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
489	     * renders as a 429 Too Many Requests response.
490	     *
491	     * @param date the registration date of the owner being created (today)
492	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
493	     */
494	    private void rejectDailyRegistrationLimit(LocalDate date) {
495	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
496	            throw new DailyOwnerRegistrationLimitException(date);
497	        }
498	    }
499	
500	    /**
501	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
502	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
503	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
504	     * day's owners identically.
505	     *
506	     * @param date the registration date to count owners for
507	     * @return the number of existing owners registered on that day
508	     */
509	    private long ownersRegisteredOn(LocalDate date) {
510	        return this.clinicService.findAllOwners().stream()
511	            .filter(owner -> date.equals(owner.getRegistrationDate()))
512	            .count();
513	    }
514	
515	    /**
516	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
517	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
518	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
519	     */
520	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
521	
522	    /**
523	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
524	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
525	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
526	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
527	     * without a registration date, such as seed data) is never flagged.
528	     *
529	     * @param date the owner's registration date (the day it was created), or {@code null}
530	     * @return {@code true} if the day already holds more than the warning threshold of owners
531	     */
532	    private boolean bulkSignupWarning(LocalDate date) {
533	        if (date == null) {
534	            return false;
535	        }
536	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
537	    }
538	
539	    /**
540	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
541	     * The identity key consolidates the former separate telephone, email and household duplicate
542	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
543	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
544	     * key, two members of the same household (same {@code householdId}) with different telephones have
545	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
546	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
547	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
548	     *
549	     * @param owner the fully-populated owner being created (telephone, email and household id set)
550	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
551	     */
552	    private void rejectDuplicateIdentity(Owner owner) {
553	        String key = identityKey(owner);
554	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
555	        if (duplicate) {
556	            throw new DuplicateOwnerIdentityException(key);
557	        }
558	    }
559	
560	    /**
561	     * Rejects a create request that would join an existing household unless it declares the shared
562	     * household with {@code sharesHousehold}. The household is keyed on {@code (lastName, postcode)}
563	     * through the deterministic {@link #householdId(Owner)}, so any existing owner with the same last
564	     * name and postcode is a member of the same household. A second such owner is a household
565	     * duplicate and is rejected with a 409 (via {@link DuplicateOwnerIdentityException}); setting
566	     * {@code sharesHousehold} bypasses this block, so the owner is created as a declared household
567	     * member instead. Owners without a {@code householdId} (e.g. no postcode) have no household to
568	     * collide with and are always allowed.
569	     *
570	     * @param owner the fully-populated owner being created (household id set)
571	     * @param sharesHousehold whether the request declared it shares an existing household
572	     * @throws DuplicateOwnerIdentityException if the household already exists and was not declared
573	     */
574	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
575	        if (sharesHousehold) {
576	            return;
577	        }
578	        String household = owner.getHouseholdId();
579	        if (household == null) {
580	            return;
581	        }
582	        if (existingOwnerMatches(this::householdId, household)) {
583	            throw new DuplicateOwnerIdentityException(identityKey(owner));
584	        }
585	    }
586	
587	    /**
588	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
589	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
590	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
591	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
592	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
593	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
594	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
595	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
596	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
597	     *
598	     * @param owner the fully-populated owner being created (telephone normalized)
599	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
600	     */
601	    private Integer possibleDuplicateOf(Owner owner) {
602	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
603	            return null;
604	        }
605	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
606	        return this.clinicService.findAllOwners().stream()
607	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
608	                && owner.getPostcode().equals(existing.getPostcode())
609	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
610	            .map(Owner::getId)
611	            .filter(java.util.Objects::nonNull)
612	            .findFirst()
613	            .orElse(null);
614	    }
615	
616	    /**
617	     * Reduces an owner to its derived {@code identityKey}, formatted
618	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
619	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
620	     * normalized (lower-cased) email or the empty string when absent (see
621	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
622	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
623	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
624	     * single duplicate check compares this one value across owners.
625	     *
626	     * @param owner the owner to derive the identity key for
627	     * @return the owner's identity key
628	     */
629	    private String identityKey(Owner owner) {
630	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
631	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
632	        String email = normalizedEmail == null ? "" : normalizedEmail;
633	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
634	        return telephone + "|" + email + "|" + household;
635	    }
636	
637	    /**
638	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
639	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
640	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
641	     * checks reduce both an existing owner and the owner being created to the same canonical key;
642	     * this returns the matched existing owner itself, so a caller can either reject the collision or
643	     * record which owner was matched.
644	     *
645	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
646	     * @param key the canonical key of the owner being created
647	     * @return the first existing owner sharing the key, or empty when none does
648	     */
649	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
650	        return this.clinicService.findAllOwners().stream()
651	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
652	            .findFirst();
653	    }
654	
655	    /**
656	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
657	     * from each owner by {@code keyExtractor} (see {@link #findExistingOwner(Function, String)}).
658	     * The create endpoint's duplicate checks use this to reduce both an existing owner and the owner
659	     * being created to the same canonical key and reject a match.
660	     *
661	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
662	     * @param key the canonical key of the owner being created
663	     * @return {@code true} if some existing owner shares the key
664	     */
665	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
666	        return findExistingOwner(keyExtractor, key).isPresent();
667	    }
668	
669	    /**
670	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
671	     * shared {@code householdId}.
672	     */
673	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
674	
675	    /**
676	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
677	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
678	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
679	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
680	     *
681	     * @param value the raw field value, or {@code null}
682	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
683	     */
684	    private String canonicalizeHousehold(String value) {
685	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
686	    }
687	
688	    /**
689	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
690	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
691	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
692	     * for the last-name normalization), so every owner with the same last name and postcode -
693	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
694	     * a postcode have no household basis and are given no household id ({@code null}).
695	     *
696	     * @param owner the owner being created
697	     * @return the shared household identifier, or {@code null} when the owner has no postcode
698	     */
699	    private String householdId(Owner owner) {
700	        String postcode = owner.getPostcode();
701	        if (postcode == null || postcode.isBlank()) {
702	            return null;
703	        }
704	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
705	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
706	    }
707	
708	    /**
709	     * Number of leading hex characters of the household hash retained as the shared
710	     * {@code householdId}.
711	     */
712	    private static final int HOUSEHOLD_ID_LENGTH = 12;
713	
714	    /**
715	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
716	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
717	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
718	     * so every such identifier is produced by the same algorithm and differs only in the value it
719	     * hashes and the number of hex characters it keeps.
720	     *
721	     * @param input the value to hash
722	     * @param length the number of leading hex characters to keep
723	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
724	     */
725	    private String hashPrefix(String input, int length) {
726	        try {
727	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
728	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
729	            StringBuilder sb = new StringBuilder(digest.length * 2);
730	            for (byte b : digest) {
731	                sb.append(String.format("%02X", b));
732	            }
733	            return sb.substring(0, length);
734	        } catch (java.security.NoSuchAlgorithmException e) {
735	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
736	        }
737	    }
738	}
